173	// SessionStore reads and writes committed sessions.
174	type SessionStore interface {
175		SessionReader
176		SessionWriter
177	}
178	
179	// Reader reads committed checkpoint documents.
180	type Reader interface {
181		ListCheckpoints(ctx context.Context) ([]CommittedInfo, error)
182		ReadCheckpoint(ctx context.Context, checkpointID id.CheckpointID) (*CheckpointSummary, error)
183	}
