39	// ReadCommittedCheckpoint reads a committed checkpoint summary and normalizes
40	// a nil store response into ErrCheckpointNotFound.
41	func ReadCommittedCheckpoint(ctx context.Context, reader CommittedReader, checkpointID id.CheckpointID) (*CheckpointSummary, error) {
42		if err := ctx.Err(); err != nil {
43			return nil, err //nolint:wrapcheck // Propagating context cancellation
44		}
45	
46		summary, err := reader.ReadCommitted(ctx, checkpointID)
47		if err != nil {
48			return nil, fmt.Errorf("read committed checkpoint: %w", err)
49		}
50		if summary == nil {
51			return nil, ErrCheckpointNotFound
52		}
53		return summary, nil
54	}
55	
56	// ReadLatestSessionContent reads the latest session from an already-resolved
57	// committed reader and summary.
58	func ReadLatestSessionContent(ctx context.Context, reader CommittedReader, checkpointID id.CheckpointID, summary *CheckpointSummary) (*SessionContent, error) {
59		if summary == nil || len(summary.Sessions) == 0 {
60			return nil, ErrCheckpointNotFound
61		}
62		latestIndex := len(summary.Sessions) - 1
63		content, err := reader.ReadSessionContent(ctx, checkpointID, latestIndex)
64		if err != nil {
65			return nil, fmt.Errorf("read session %d content: %w", latestIndex, err)
66		}
67		return content, nil
68	}
69	
70	func ReadRawSessionLogForCheckpoint(ctx context.Context, reader CommittedReader, checkpointID id.CheckpointID) ([]byte, string, error) {
71		if err := ctx.Err(); err != nil {
72			return nil, "", err //nolint:wrapcheck // Propagating context cancellation
73		}
74	
75		summary, err := ReadCommittedCheckpoint(ctx, reader, checkpointID)
76		if err != nil {
77			return nil, "", err
78		}
79	
80		content, err := ReadLatestSessionContent(ctx, reader, checkpointID, summary)
81		if err != nil {
82			return nil, "", err
83		}
84		return content.Transcript, content.Metadata.SessionID, nil
85	}

