		Transcript:   redact.AlreadyRedacted([]byte("first transcript\n")),
		AuthorName:   "Test",
		AuthorEmail:  "test@example.com",
	}))
	require.NoError(t, store.Write(ctx, WriteSession{
		CheckpointID: cpID,
		SessionID:    "session-b",
